import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:font_awesome_flutter/font_awesome_flutter.dart';import '../../../../Core/Utils/Extensions/context_extension.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../../Core/Resources/app_colors.dart';import '../../../../Core/Resources/app_fonts.dart';import 'build_item_setting.dart';import 'language_selector.dart';class BuildBodySetting extends StatelessWidget {  const BuildBodySetting({    super.key,  });  @override  Widget build(BuildContext context) {    return SliverFillRemaining(      fillOverscroll: true,      hasScrollBody: false,      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        children: [          Padding(            padding: const EdgeInsets.symmetric(vertical: 24).r,            child: Text(              "Setting",              style: AppTextStyles.h7Bold.copyWith(                color: AppColors.grayscale60,              ),            ),          ),          BuildItemSetting(            title: context.local.YourCard,            icon: FaIcon(FontAwesomeIcons.creditCard),            onTap: () {},          ),          BuildItemSetting(            title: context.local.Security,            icon: FaIcon(FontAwesomeIcons.shield),            onTap: () {},          ),          BuildItemSetting(            title: context.local.Languages,            icon: FaIcon(FontAwesomeIcons.globe),            onTap: () {              context.showCustomBottomSheet(builder: (BuildContext context) {                return LanguageList();              });            },          ),          BuildItemSetting(            title: context.local.Info,            icon: FaIcon(FontAwesomeIcons.circleInfo),            onTap: () {},          ),        ],      ),    );  }}